if (Number.isInteger(legacyDryLiveRaw) && legacyDryLiveRaw >= 0 && legacyDryLiveRaw <= 255) {
    const dryDefinitions = [{ index: 1, mask: 0x02 }, { index: 2, mask: 0x04 }];
    for (const dry of dryDefinitions) {
