// Récupérer ou initialiser le tableau
let tableau_0x1114 = global.get('0x1114') || [];

// Extraire les données
let uint16_value = msg.payload["0x1114"];  // ex: 0x0210 (valeur UINT16)
let bms_number = global.get('slaveAddress-Trame2');  // 0 à 15
//let bms_number = msg.payload["Device_address_N"] ;  // 0 à 15

// Vérifier si ce bms_number existe déjà
let index = tableau_0x1114.findIndex(item => item[1] === bms_number);

if (index !== -1) {
    // Mettre à jour la ligne existante
    tableau_0x1114[index] = [uint16_value, bms_number];
} else {
    // Ajouter une nouvelle ligne
    tableau_0x1114.push([uint16_value, bms_number]);
}

// Sauvegarder dans le contexte global
global.set('0x1114', tableau_0x1114);

// Afficher les détails pour debug
msg.payload = {
    bms: bms_number,
    value: uint16_value,
    value_hex: "0x" + uint16_value.toString(16).toUpperCase().padStart(4, '0'),
    value_binary: "0b" + uint16_value.toString(2).padStart(16, '0'),
    bit9: (uint16_value & 0x0200) ? 1 : 0  // État du bit 9
};

return msg;

let currentAddress = global.get("slaveAddress-Trame2") || 1; // Valeur par défaut : 1
let Number_of_BMS = global.get("nb_jkbms") || 1; // Valeur par défaut : 1

// Incrémenter l'adresse, revenir à 1 après 8
currentAddress = currentAddress >= Number_of_BMS ? 1 : currentAddress + 1;

global.set("slaveAddress-Trame2", currentAddress);

//node.warn(`Prochaine adresse esclave Trame2 : ${currentAddress}`);
msg.payload = currentAddress;
return msg; // Continuer vers le prochain nœud

var BMS = msg.payload.SerialNb_N;
// Pour debug, affichons la valeur BMS
node.warn(`BMS SerialNb: ${BMS} is alive`);
return msg;

// Récupération de l'ID d'esclave
const slaveId = global.get("slaveAddress-Trame1") || 0x01;
const slaveIdNumber = typeof slaveId === 'string' ? parseInt(slaveId, 16) : slaveId;

// 4.1.12-alpha4: capture both shared-register neighbor bytes from a true STATIC frame.
// Do not expose these implementation bytes as Home Assistant entities.
if (msg.payload && typeof msg.payload === 'object') {
    const data = msg.payload;
    const n1 = Number(data._dry1_neighbor_byte_N);
    const n2 = Number(data._dry2_neighbor_byte_N);
    const c1 = Number(data.DRY1_trigger_code_N);
    const c2 = Number(data.DRY2_trigger_code_N);
    if ([n1,n2,c1,c2].every(v => Number.isInteger(v) && v>=0 && v<=255) && slaveIdNumber>=1 && slaveIdNumber<=15) {
        global.set('dry_alpha4_static_BMS_'+slaveIdNumber, {
            time: Date.now(), dry1: [n1,c1], dry2: [c2,n2]
        });
    }
    delete data._dry1_neighbor_byte_N;
    delete data._dry2_neighbor_byte_N;
}

// alpha6: verify against the actual decoded STATIC frame, never an optimistic MQTT state.
// Track only physical BMS_1..15 (no Master alias), and do not change existing MQTT states.
if (msg.payload && typeof msg.payload==='object' && slaveIdNumber>=1 && slaveIdNumber<=15) {
    const fields={
        dry1_trigger_code:'DRY1_trigger_code_N',
        dry2_trigger_code:'DRY2_trigger_code_N',
        dry1_trigger_value:'DRY1_trigger_value_RAW',
        dry1_release_value:'DRY1_release_value_RAW',
        dry2_trigger_value:'DRY2_trigger_value_RAW',
        dry2_release_value:'DRY2_release_value_RAW'
    };
    const now=Date.now();
    for (const [key,field] of Object.entries(fields)) {
        const token='dry_alpha6_pending_BMS_'+slaveIdNumber+'_'+key;
        const p=global.get(token);
        if (!p) continue;
        if (now>=p.deadline) {
            node.warn('DRY READBACK TIMEOUT BMS_'+slaveIdNumber+' '+key+' requested '+p.requested);
            global.set(token,null);
            continue;
        }
        // The parser's message must have arrived after the outgoing command.
        if (now<p.started || !Object.prototype.hasOwnProperty.call(msg.payload,field)) continue;
        const actual=Number(msg.payload[field]);
        if (!Number.isFinite(actual)) continue;
        if (actual===p.requested) {
            node.warn('DRY STATIC VERIFIED BMS_'+slaveIdNumber+' '+key+' = '+actual);
            global.set(token,null);
        } else {
            // Mismatch may be transient while the device processes the write.
            node.debug('DRY STATIC pending BMS_'+slaveIdNumber+' '+key+' actual '+actual+' expected '+p.requested);
        }
    }
}

// ------------------------------------------------------------------
// 1. Vérrou : discovery une seule fois (cohérent avec l'initialisation)
const discoveryKey = `discoverySent_STATIC_BMS_${slaveIdNumber}`;
const discoveryAlreadySent = flow.get(discoveryKey) || false;

// ------------------------------------------------------------------
// 2. Constantes
const baseTopic = "BMS_" + slaveIdNumber;
// alpha5: user-facing JK labels, source numeric topics retained for backward compatibility.
const drySourceLabels = ["00 - OFF", "01 - Low SOC", "02 - Battery Over Voltage", "03 - Battery Under Voltage", "04 - Battery Cell Over Voltage", "05 - Battery Cell Under Voltage", "06 - Charge Over Current", "07 - Discharge Over Current", "08 - Battery over Temperature", "09 - MOSFET Over Temperature", "10 - SysAlarm", "11 - Battery Low Temperature", "12 - Remote Control", "13 - Above SOC", "14 - MOSFET Abnormal"];
const discoveryPrefix = "homeassistant";
const deviceName = "BMS_" + slaveIdNumber;
const deviceID = "BMS_" + slaveIdNumber + "_device";

// Champs qui doivent être des "number" (configuration)
const numberFields = [
    "LCD_buzzer_trigger_N", 
    "LCD_buzzer_trigger_value_N", 
    "LCD_buzzer_release_value_N",
    "Request_Charge_voltage_Time_H",
    "Request_Float_voltage_Time_H",
    "DRY1_trigger_code_N",
    "DRY2_trigger_code_N",
    "DRY1_trigger_value_RAW",
    "DRY1_release_value_RAW",
    "DRY2_trigger_value_RAW",
    "DRY2_release_value_RAW"
];

// ------------------------------------------------------------------
// 3. Fonctions de génération
function formatValue(v) {
    return (typeof v === 'string') ? v : String(v);
}

function buildDiscoveryMessages(payloadObj) {
    const msgs = [];
    for (const key in payloadObj) {
        const cleanKey = key.replace(/_[A-Z]+$/, "").toLowerCase();
        const sensorTopic = `${baseTopic}/state/${cleanKey}`;

        // Vérifier si c'est un champ "number" (configuration)
        if (numberFields.includes(key)) {
            const commandTopic = `${baseTopic}/control/${cleanKey}/set`;

            // Définir la plage selon le champ
            let min = 0;
            let max = 100;
            let unit = "%";
            let step = 1;
            let icon = "mdi:tune";

            if (/^DRY[12]_(trigger|release)_value_RAW$/.test(key)) {
                min = -100000;
                max = 100000;
                unit = "";
                step = 1;
                icon = "mdi:electric-switch";
            } else if (key === "LCD_buzzer_trigger_N") {
                max = 25;
                unit = "";
                icon = "mdi:volume-high";
            } else if (key === "Request_Charge_voltage_Time_H" || key === "Request_Float_voltage_Time_H") {
                min = 0;
                max = 25;
                step = 0.1;
                unit = "h";
                icon = "mdi:timer-outline";
            }

            const isDrySource = key === "DRY1_trigger_code_N" || key === "DRY2_trigger_code_N";
            let cfg = {
                name: `BMS ${key.replace(/_[A-Z]+$/, "").replace(/_/g, " ")}`,
                unique_id: `${deviceID}_static_bms_${cleanKey}_v4`,
                state_topic: sensorTopic,
                command_topic: commandTopic,
                min: min,
                max: max,
                step: step,
                mode: "box",
                entity_category: "config",
                enabled_by_default: true,
                icon: icon,
                device: {
                    identifiers: [deviceID],
                    name: deviceName,
                    manufacturer: "Smartphoton-JK-BMS / ©JLM 2025-2026",
                    model: payloadObj.BMS_A || "rs485 vers MQTT",
                    sw_version: payloadObj.SW_N || "3.5"
                }
            };

            if (isDrySource) {
                // Select state and command payloads use the numeric source codes 0..14.
                // A new select unique ID avoids colliding with any existing retained sensor.
                cfg.unique_id += '_alpha4_select';
                cfg.options = drySourceLabels.slice();
                cfg.state_topic = `${baseTopic}/state/${cleanKey}_label`;
                delete cfg.min; delete cfg.max; delete cfg.step; delete cfg.mode;
                cfg.icon = 'mdi:electric-switch';
            }
            // Ajouter l'unité seulement si elle existe
            if (unit && !isDrySource) {
                cfg.unit_of_measurement = unit;
            }

            // Force l'entity_id HA stable pour les number statics
            cfg.object_id = `${baseTopic.toLowerCase()}_bms_${cleanKey}`;
            cfg.default_entity_id = `${isDrySource?'select':'number'}.${cfg.object_id}`;

            msgs.push({
                topic: `${discoveryPrefix}/${isDrySource?'select':'number'}/${cfg.object_id}/config`,
                payload: JSON.stringify(cfg),
                retain: true
            });
        } else {
            // Capteur classique (sensor)
            let cfg = {
                name: `BMS ${key.replace(/_[A-Z]+$/, "").replace(/_/g, " ")}`,
                unique_id: `${deviceID}_static_bms_${cleanKey}_v4`,
                state_topic: sensorTopic,
                enabled_by_default: true,
                // \u274c SUPPRESSION de "entity_category: diagnostic"
                device: {
                    identifiers: [deviceID],
                    name: deviceName,
                    manufacturer: "Smartphoton-JK-BMS / ©JLM 2025",
                    model: payloadObj.BMS_A || "rs485 vers MQTT",
                    sw_version: payloadObj.SW_N || "3.3"
                }
            };

            // unités & classes
            if (key.endsWith("_S")) {
                cfg.unit_of_measurement = "s";
                cfg.device_class = "duration";
                cfg.state_class = "measurement";
            } else if (key.endsWith("_H")) {
                cfg.unit_of_measurement = "h";
                cfg.device_class = "duration";
                cfg.state_class = "measurement";
            } else if (key.endsWith("_N") && key.includes("Time")) {
                cfg.unit_of_measurement = "s";
                cfg.device_class = "duration";
                cfg.state_class = "measurement";
            } else if (key.endsWith("_N") && !key.includes("Serial")) {
                cfg.state_class = "measurement";
            }

            // icônes
            if (key.includes("Password")) cfg.icon = "mdi:form-textbox-password";
            else if (key.includes("Serial")) cfg.icon = "mdi:barcode";
            else if (key.includes("protocol")) cfg.icon = "mdi:protocol";
            else if (key.includes("version") || key.includes("SW") || key.includes("FW"))
                cfg.icon = "mdi:numeric-10";
            else if (key.includes("Uptime")) {
                cfg.icon = "mdi:timer-outline";
                cfg.device_class = "duration";
            } else if (key.includes("date")) cfg.icon = "mdi:calendar";

            // Force l'entity_id HA stable pour les sensor statics
            cfg.object_id = `${baseTopic.toLowerCase()}_bms_${cleanKey}`;
            cfg.default_entity_id = `sensor.${cfg.object_id}`;

            msgs.push({
                topic: `${discoveryPrefix}/sensor/${cfg.object_id}/config`,
                payload: JSON.stringify(cfg),
                retain: true
            });
        }
    }
    return msgs;
}

function buildStateMessages(payloadObj) {
    const msgs = [];
    for (const key in payloadObj) {
        const cleanKey = key.replace(/_[A-Z]+$/, "").toLowerCase();
        msgs.push({
            topic: `${baseTopic}/state/${cleanKey}`,
            payload: formatValue(payloadObj[key]),
            retain: true
        });
        if (key === 'DRY1_trigger_code_N' || key === 'DRY2_trigger_code_N') {
            const code = Number(payloadObj[key]);
            if (Number.isInteger(code) && code >= 0 && code < drySourceLabels.length) {
                msgs.push({topic: `${baseTopic}/state/${cleanKey}_label`, payload: drySourceLabels[code], retain: true});
            }
        }
    }
    return msgs;
}

// ------------------------------------------------------------------
// 4. Construction des messages
const payload = msg.payload;

var outputMsgs = [];

// Envoyer les messages de discovery seulement si pas déjà fait
if (!discoveryAlreadySent) {
    outputMsgs = buildDiscoveryMessages(payload);
    flow.set(discoveryKey, true);
}

// Ajouter les messages de state
const stateMsgs = buildStateMessages(payload);
outputMsgs = outputMsgs.concat(stateMsgs);

return [outputMsgs];

let currentAddress = global.get("slaveAddress-Trame1") || 1; // Valeur par défaut : 1
let Number_of_BMS = global.get("nb_jkbms") || 1; // Valeur par défaut : 1

// Incrémenter l'adresse, revenir à 1 après 8
currentAddress = currentAddress >= Number_of_BMS ? 1 : currentAddress + 1;

global.set("slaveAddress-Trame1", currentAddress);

//node.warn(`Prochaine adresse esclave Trame1 : ${currentAddress}`);
msg.payload = currentAddress;
return msg; // Continuer vers le prochain nœud

let currentAddress = global.get("slaveAddress-Trame3") || 1; // Valeur par défaut : 1
let Number_of_BMS = global.get("nb_jkbms") || 1; // Valeur par défaut : 1

// Incrémenter l'adresse, revenir à 1 après 8
currentAddress = currentAddress >= Number_of_BMS ? 1 : currentAddress + 1;

global.set("slaveAddress-Trame3", currentAddress);

// node.warn(`Prochaine adresse esclave Trame3 : ${currentAddress}`);
msg.payload = currentAddress;
return msg; // Continuer vers le prochain nœud

// ========== LECTURE DES ALARMES JK-BMS ==========
// Lecture registre 0x12A0 - alarmes UINT32
// Corrigé : boucle dédiée sur tous les BMS pour créer les alarmes BMS 1/2/3/...

const totalBms = Number(global.get("nb_jkbms")) || 1;

let slaveId = Number(global.get("slaveAddress-Trame4")) || 1;
if (slaveId < 1 || slaveId > totalBms) slaveId = 1;

// Prépare déjà le prochain BMS pour le prochain passage
let nextSlaveId = slaveId >= totalBms ? 1 : slaveId + 1;
global.set("slaveAddress-Trame4", nextSlaveId);

const functionCode = 0x03;
const address = 0x12A0;

function crc16(buffer) {
    let crc = 0xFFFF;
    for (let i = 0; i < buffer.length; i++) {
        crc ^= buffer[i];
        for (let j = 0; j < 8; j++) {
            crc = (crc & 1) ? (crc >> 1) ^ 0xA001 : crc >> 1;
        }
    }
    return crc;
}

const dataBuffer = Buffer.from([
    slaveId,
    functionCode,
    (address >> 8) & 0xFF,
    address & 0xFF,
    0x00,
    0x02
]);

const crc = crc16(dataBuffer);
const finalBuffer = Buffer.allocUnsafe(dataBuffer.length + 2);
dataBuffer.copy(finalBuffer);
finalBuffer.writeUInt16LE(crc, dataBuffer.length);

msg.topic = "Trame-Alarmes-BMS";
msg.payload = finalBuffer;

msg.bmsId = slaveId;
msg.bms_id = slaveId;
msg.bms_numero = slaveId;

flow.set("last_alarm_request_bms", slaveId);

return msg;

let interval = Number(global.get("non_broadcasting_data_interval_s"));

if (!isFinite(interval)) interval = 1;
if (interval < 1) interval = 1;
if (interval > 30) interval = 30;

const immediate = { ...msg };
delete immediate.delay;

const nextTick = {
    payload: msg.payload,
    host: msg.host,
    port: msg.port,
    delay: Math.round(interval * 1000) // ms
};

return [immediate, nextTick];

let p = msg.payload || {};

let cellCount = Number(p.cell_count_N);
if (!Number.isFinite(cellCount) || cellCount < 1) {
    cellCount = 16;
}

// Borné à 16 car le parser actuel de la trame 3 va jusqu'à Cell_16_volt_V
cellCount = Math.min(cellCount, 16);

global.set("jk_cell_count", cellCount);
msg.cell_count_N = cellCount;

return msg;

let slot = flow.get('gateway_tcp_slot') || 'A';
if (slot !== 'B') slot = 'A';
node.status({fill:'blue',shape:'dot',text:'slot ' + slot});
return slot === 'A' ? [msg, null] : [null, msg];

flow.set('lastDataTs_master', 0);
flow.set('gateway_status_master', 'unknown');
flow.set('gateway_tcp_slot', 'A');
flow.set('failoverTs_master', 0);
node.status({fill:'grey',shape:'ring',text:'slot A'});
return null;

const slot = flow.get('gateway_tcp_slot') || 'A';
flow.set('lastDataTs_master', Date.now());
flow.set('gateway_status_master', slot === 'A' ? 'online' : 'online_B');
flow.set('failoverTs_master', 0);
flow.set('failoverCount_master', 0); // ← reset compteur dès données reçues
return null;

const TIMEOUT_MS   = 120000;
const MAX_FAILOVER = 4; // 2 allers-retours max

if (global.get('use_gateway') !== true) return null;

// Abandon si gateway déclarée injoignable
if (flow.get('gateway_status_master') === 'unreachable') return null;

const last       = flow.get('lastDataTs_master') || 0;
const failoverTs = flow.get('failoverTs_master') || 0;

if (last === 0 && failoverTs === 0) return null;

const ref     = last > 0 ? last : failoverTs;
const elapsed = Date.now() - ref;

if (elapsed <= TIMEOUT_MS) return null;

const count   = (flow.get('failoverCount_master') || 0) + 1;
const current = flow.get('gateway_tcp_slot') || 'A';
const next    = current === 'A' ? 'B' : 'A';

if (count >= MAX_FAILOVER) {
    flow.set('gateway_status_master', 'unreachable');
    flow.set('failoverCount_master', count);
    node.warn(`Gateway master: aucune réponse après ${count} basculements → abandon`);
    return [{ payload: { status: 'unreachable', attempts: count } }];
}

flow.set('gateway_tcp_slot', next);
flow.set('gateway_status_master', 'failover');
flow.set('lastDataTs_master', 0);
flow.set('failoverTs_master', Date.now());
flow.set('failoverCount_master', count);

node.warn(`Gateway watchdog: timeout ${Math.round(elapsed/1000)}s -> failover ${current} => ${next} (tentative ${count}/${MAX_FAILOVER})`);
return [{ payload: { status: 'failover', from: current, to: next, elapsed_s: Math.round(elapsed/1000), attempt: count } }];

// Unified diagnostics - active polling: poll sent
// Transparent node: payload and business logic are not modified.

if (global.get("bms_broadcasting") === true) {
    return msg;
}

const now = Date.now();

function normalizeFrameType(topic) {
    const t = String(topic || "").toLowerCase();
    if (t.includes("trame-3") || t.includes("dynamic") || t.includes("live")) return "live";
    if (t.includes("trame-2") || t.includes("setup")) return "setup";
    if (t.includes("trame-1") || t.includes("static")) return "static";
    if (t.includes("alarm")) return "alarms";
    return t || "other";
}

let s = flow.get("diag_active_polling_stats") || {};
s.first_ts = s.first_ts || now;
s.polls_sent_30s = s.polls_sent_30s || 0;
s.responses_received_30s = s.responses_received_30s || 0;
s.valid_responses_30s = s.valid_responses_30s || 0;
s.response_time_sum_ms_30s = s.response_time_sum_ms_30s || 0;
s.response_time_count_30s = s.response_time_count_30s || 0;
s.max_response_time_ms_30s = s.max_response_time_ms_30s || 0;
s.pending = s.pending || {};
s.responding_seen = s.responding_seen || {};
s.polls_by_slave_30s = s.polls_by_slave_30s || {};
s.valid_by_slave_30s = s.valid_by_slave_30s || {};
s.timeouts_by_slave_30s = s.timeouts_by_slave_30s || {};
s.polls_by_frame_30s = s.polls_by_frame_30s || {};
s.valid_by_frame_30s = s.valid_by_frame_30s || {};
s.live_valid_by_slave_30s = s.live_valid_by_slave_30s || {};
s.last_valid_by_slave = s.last_valid_by_slave || {};
s.live_cycle_seen = s.live_cycle_seen || {};
s.complete_poll_cycles_30s = s.complete_poll_cycles_30s || 0;
s.cycle_time_sum_ms_30s = s.cycle_time_sum_ms_30s || 0;
s.cycle_time_count_30s = s.cycle_time_count_30s || 0;
s.max_cycle_time_ms_30s = s.max_cycle_time_ms_30s || 0;
s.seq = (Number(s.seq) || 0) + 1;

const buf = Buffer.isBuffer(msg.payload) ? msg.payload : null;
const slaveId = buf && buf.length > 0
    ? Number(buf[0])
    : Number(msg.bms_id || msg.bmsId || msg.bms_numero);
const rawFrameType = String(msg.topic || "unknown");
const frameType = normalizeFrameType(rawFrameType);
const txId = `${now}-${s.seq}`;

msg.diag_tx_id = txId;
msg.diag_poll_ts = now;
msg.diag_slave_id = Number.isFinite(slaveId) ? slaveId : null;
msg.diag_frame_type = frameType;
msg.diag_frame_topic = rawFrameType;

s.polls_sent_30s += 1;
s.last_poll_ts = now;
s.last_poll_slave_id = Number.isFinite(slaveId) ? slaveId : null;
s.last_poll_frame_type = frameType;
s.pending[txId] = {
    ts: now,
    slave_id: Number.isFinite(slaveId) ? slaveId : null,
    frame_type: frameType,
    frame_topic: rawFrameType
};

if (Number.isFinite(slaveId) && slaveId > 0) {
    const key = String(slaveId);
    s.polls_by_slave_30s[key] = (s.polls_by_slave_30s[key] || 0) + 1;
}
s.polls_by_frame_30s[frameType] = (s.polls_by_frame_30s[frameType] || 0) + 1;

flow.set("diag_active_polling_stats", s);
return msg;

// Unified diagnostics - active polling: response received
// Transparent tap on the common serial/TCP response path.

if (global.get("bms_broadcasting") === true) {
    return null;
}

const now = Date.now();
let s = flow.get("diag_active_polling_stats") || {};
s.responses_received_30s = (s.responses_received_30s || 0) + 1;
s.last_response_ts = now;
s.pending = s.pending || {};

let latency = null;
let matchedId = msg.diag_tx_id ? String(msg.diag_tx_id) : null;

if (Number.isFinite(Number(msg.diag_poll_ts))) {
    latency = Math.max(0, now - Number(msg.diag_poll_ts));
} else {
    // Fallback for request nodes that do not preserve custom properties.
    // In this flow only one request is normally outstanding, so the oldest
    // pending transaction is the safest deterministic match.
    let bestId = null;
    let bestTs = Infinity;
    for (const [id, p] of Object.entries(s.pending)) {
        if (Number(p.ts) < bestTs) {
            bestTs = Number(p.ts);
            bestId = id;
        }
    }
    if (bestId) {
        matchedId = bestId;
        const p = s.pending[bestId];
        msg.diag_tx_id = bestId;
        msg.diag_poll_ts = Number(p.ts);
        msg.diag_slave_id = p.slave_id;
        msg.diag_frame_type = p.frame_type;
        latency = Math.max(0, now - Number(p.ts));
    }
}

if (latency !== null) msg.diag_response_time_ms = latency;
if (matchedId && s.pending[matchedId]) {
    s.last_response_slave_id = s.pending[matchedId].slave_id;
    s.last_response_frame_type = s.pending[matchedId].frame_type;
}

flow.set("diag_active_polling_stats", s);
return null;

// Unified diagnostics - active polling: valid decoded response
// Connect this node in parallel only after an existing frame validator/decoder.

if (global.get("bms_broadcasting") === true) {
    return null;
}

const now = Date.now();

function normalizeFrameType(topic) {
    const t = String(topic || "").toLowerCase();
    if (t.includes("trame-3") || t.includes("dynamic") || t.includes("live")) return "live";
    if (t.includes("trame-2") || t.includes("setup")) return "setup";
    if (t.includes("trame-1") || t.includes("static")) return "static";
    if (t.includes("alarm")) return "alarms";
    return t || "other";
}

let s = flow.get("diag_active_polling_stats") || {};
s.pending = s.pending || {};
s.responding_seen = s.responding_seen || {};
s.polls_by_slave_30s = s.polls_by_slave_30s || {};
s.valid_by_slave_30s = s.valid_by_slave_30s || {};
s.timeouts_by_slave_30s = s.timeouts_by_slave_30s || {};
s.polls_by_frame_30s = s.polls_by_frame_30s || {};
s.valid_by_frame_30s = s.valid_by_frame_30s || {};
s.live_valid_by_slave_30s = s.live_valid_by_slave_30s || {};
s.last_valid_by_slave = s.last_valid_by_slave || {};
s.live_cycle_seen = s.live_cycle_seen || {};
s.complete_poll_cycles_30s = s.complete_poll_cycles_30s || 0;
s.cycle_time_sum_ms_30s = s.cycle_time_sum_ms_30s || 0;
s.cycle_time_count_30s = s.cycle_time_count_30s || 0;
s.max_cycle_time_ms_30s = s.max_cycle_time_ms_30s || 0;

let txId = msg.diag_tx_id ? String(msg.diag_tx_id) : null;
let slaveId = Number(msg.diag_slave_id);
let frameType = msg.diag_frame_type ? String(msg.diag_frame_type) : normalizeFrameType(msg.topic);

if (!Number.isFinite(slaveId)) slaveId = Number(msg.bms_id || msg.bmsId || msg.bms_numero);
if (!Number.isFinite(slaveId) && Buffer.isBuffer(msg.payload) && msg.payload.length > 0) {
    slaveId = Number(msg.payload[0]);
}

// Match the oldest pending transaction that agrees with the known slave/frame.
if (!txId || !s.pending[txId]) {
    let bestId = null;
    let bestTs = Infinity;
    for (const [id, p] of Object.entries(s.pending)) {
        if (Number.isFinite(slaveId) && Number(p.slave_id) !== slaveId) continue;
        if (frameType && p.frame_type && String(p.frame_type) !== frameType) continue;
        if (Number(p.ts) < bestTs) {
            bestTs = Number(p.ts);
            bestId = id;
        }
    }
    if (!bestId) {
        // Final fallback: this flow normally has a single outstanding request.
        for (const [id, p] of Object.entries(s.pending)) {
            if (Number(p.ts) < bestTs) {
                bestTs = Number(p.ts);
                bestId = id;
            }
        }
    }
    if (bestId) txId = bestId;
}

let latency = Number(msg.diag_response_time_ms);
if (txId && s.pending[txId]) {
    const p = s.pending[txId];
    if (!Number.isFinite(slaveId)) slaveId = Number(p.slave_id);
    if (!frameType || frameType === "other") frameType = String(p.frame_type || "other");
    if (!Number.isFinite(latency)) latency = Math.max(0, now - Number(p.ts));
    delete s.pending[txId];
}

s.valid_responses_30s = (s.valid_responses_30s || 0) + 1;
s.last_valid_response_ts = now;
s.last_valid_slave_id = Number.isFinite(slaveId) ? slaveId : null;
s.last_valid_frame_type = frameType;

if (Number.isFinite(latency)) {
    s.response_time_sum_ms_30s = (s.response_time_sum_ms_30s || 0) + latency;
    s.response_time_count_30s = (s.response_time_count_30s || 0) + 1;
    s.max_response_time_ms_30s = Math.max(s.max_response_time_ms_30s || 0, latency);
}

if (Number.isFinite(slaveId) && slaveId > 0) {
    const key = String(slaveId);
    s.responding_seen[key] = now;
    s.last_valid_by_slave[key] = now;
    s.valid_by_slave_30s[key] = (s.valid_by_slave_30s[key] || 0) + 1;
    s.valid_by_frame_30s[frameType] = (s.valid_by_frame_30s[frameType] || 0) + 1;

    // A complete active polling cycle is defined by one valid live/data response
    // from every configured BMS. Static/setup/alarm requests are not part of it.
    if (frameType === "live") {
        s.live_valid_by_slave_30s[key] = (s.live_valid_by_slave_30s[key] || 0) + 1;
        s.live_cycle_seen[key] = now;

        const configuredBms = Math.max(1, Number(global.get("nb_jkbms")) || 1);
        let complete = true;
        for (let id = 1; id <= configuredBms; id++) {
            if (!s.live_cycle_seen[String(id)]) {
                complete = false;
                break;
            }
        }

        if (complete) {
            s.complete_poll_cycles_30s += 1;
            if (s.last_complete_cycle_ts) {
                const cycleMs = Math.max(0, now - Number(s.last_complete_cycle_ts));
                s.cycle_time_sum_ms_30s += cycleMs;
                s.cycle_time_count_30s += 1;
                s.max_cycle_time_ms_30s = Math.max(s.max_cycle_time_ms_30s || 0, cycleMs);
            }
            s.last_complete_cycle_ts = now;
            s.live_cycle_seen = {};
        }
    }
} else {
    s.valid_by_frame_30s[frameType] = (s.valid_by_frame_30s[frameType] || 0) + 1;
}

flow.set("diag_active_polling_stats", s);
return null;

// Unified health snapshot - module master active polling
// Publishes on the same topic/entity as broadcast diagnostics.

if (global.get("bms_broadcasting") === true) {
    return null;
}

const now = Date.now();
const SNAPSHOT_SECONDS = 30;
const PENDING_TIMEOUT_MS = 5000;
const BMS_SEEN_WINDOW_MS = 120000;
const STARTUP_GRACE_MS = 30000;

let s = flow.get("diag_active_polling_stats") || {};
s.first_ts = s.first_ts || now;
s.total_timeouts = Number(s.total_timeouts) || 0;
s.last_timeout_ts = Number(s.last_timeout_ts) || 0;
const storedWorstScore = s.worst_health_score;
s.worst_health_score =
    storedWorstScore === null ||
    storedWorstScore === undefined ||
    storedWorstScore === "" ||
    !Number.isFinite(Number(storedWorstScore))
        ? null
        : Number(storedWorstScore);
s.worst_health_reason = s.worst_health_reason || "";
s.worst_health_flags_text = s.worst_health_flags_text || "none";
s.worst_score_detail = s.worst_score_detail || "";
s.worst_health_ts = Number(s.worst_health_ts) || 0;
s.health_incident_count = Number(s.health_incident_count) || 0;
s.previous_health_status = s.previous_health_status || "starting";

function humanReason(code) {
    const map = {
        healthy: "Communication is operating normally",
        healthy_active_polling: "All configured BMS respond normally",
        healthy_single_bms_broadcast: "The single broadcast BMS is communicating normally",
        healthy_multi_bms_broadcast: "All detected broadcast BMS are communicating normally",
        healthy_broadcast: "Broadcast communication is operating normally",
        healthy_multi_bms_broadcast_concat: "Broadcast communication is healthy despite concatenated buffers",
        waiting_for_serial_data: "Waiting for the first communication data",
        serial_timeout: "No communication data has been received recently",
        serial_slow: "Communication data is arriving more slowly than expected",
        excessive_fragmentation: "Input buffers are unusually fragmented",
        no_valid_frames_emitted: "Data is received but no valid JK-BMS frame is reconstructed",
        low_frame_yield: "Too few candidate frames are reconstructed successfully",
        polling_stopped: "The module is not issuing polling requests",
        no_bms_response: "Polling requests are sent but no BMS responds",
        one_bms_not_responding: "One configured BMS is not responding",
        multiple_bms_not_responding: "Several configured BMS are not responding",
        partial_bms_response: "Only part of the configured BMS set is responding",
        high_timeout_rate: "Too many polling requests end in timeout",
        invalid_response_frames: "Some received responses do not pass validation",
        stale_complete_cycle: "A complete live-data polling cycle has not finished recently",
        starting: "Diagnostics are starting"
    };
    return map[code] || String(code || "Unknown diagnostic reason").replace(/_/g, " ");
}

function formatDuration(totalSeconds) {
    const s = Math.max(0, Math.floor(Number(totalSeconds) || 0));
    const d = Math.floor(s / 86400);
    const h = Math.floor((s % 86400) / 3600);
    const m = Math.floor((s % 3600) / 60);
    const sec = s % 60;
    if (d > 0) return `${d}d ${h}h ${m}m`;
    if (h > 0) return `${h}h ${m}m`;
    if (m > 0) return `${m}m ${sec}s`;
    return `${sec}s`;
}

s.pending = s.pending || {};
s.responding_seen = s.responding_seen || {};
s.polls_by_slave_30s = s.polls_by_slave_30s || {};
s.valid_by_slave_30s = s.valid_by_slave_30s || {};
s.timeouts_by_slave_30s = s.timeouts_by_slave_30s || {};
s.polls_by_frame_30s = s.polls_by_frame_30s || {};
s.valid_by_frame_30s = s.valid_by_frame_30s || {};
s.live_valid_by_slave_30s = s.live_valid_by_slave_30s || {};
s.last_valid_by_slave = s.last_valid_by_slave || {};
s.live_cycle_seen = s.live_cycle_seen || {};

let expiredTimeouts = 0;
for (const [id, p] of Object.entries(s.pending)) {
    if ((now - Number(p.ts || 0)) > PENDING_TIMEOUT_MS) {
        expiredTimeouts += 1;
        const slaveKey = Number.isFinite(Number(p.slave_id)) ? String(Number(p.slave_id)) : "unknown";
        s.timeouts_by_slave_30s[slaveKey] = (s.timeouts_by_slave_30s[slaveKey] || 0) + 1;
        s.total_timeouts += 1;
        s.last_timeout_ts = now;
        delete s.pending[id];
    }
}

for (const [id, ts] of Object.entries(s.responding_seen)) {
    if ((now - Number(ts || 0)) > BMS_SEEN_WINDOW_MS) delete s.responding_seen[id];
}

const configuredBms = Math.max(1, Number(global.get("nb_jkbms")) || 1);
const configuredList = Array.from({length: configuredBms}, (_, i) => i + 1);
const respondingList = Object.keys(s.responding_seen)
    .map(Number)
    .filter(v => Number.isFinite(v) && v > 0)
    .sort((a, b) => a - b);
const respondingSet = new Set(respondingList);
const missingList = configuredList.filter(id => !respondingSet.has(id));

const pollsSent = Number(s.polls_sent_30s) || 0;
const responsesReceived = Number(s.responses_received_30s) || 0;
const validResponses = Number(s.valid_responses_30s) || 0;
const timeouts = expiredTimeouts;
const invalidResponses = Math.max(0, responsesReceived - validResponses);
const successRatio = pollsSent > 0 ? Number((validResponses / pollsSent).toFixed(3)) : 0;
const pollingRateRps = Number((pollsSent / SNAPSHOT_SECONDS).toFixed(3));

const avgResponseMs = (s.response_time_count_30s || 0) > 0
    ? Math.round((s.response_time_sum_ms_30s || 0) / s.response_time_count_30s)
    : null;
const maxResponseMs = (s.response_time_count_30s || 0) > 0
    ? Math.round(s.max_response_time_ms_30s || 0)
    : null;

const completeCycles = Number(s.complete_poll_cycles_30s) || 0;
const cycleRatePerMin = Number((completeCycles * (60 / SNAPSHOT_SECONDS)).toFixed(2));
const avgCycleMs = (s.cycle_time_count_30s || 0) > 0
    ? Math.round((s.cycle_time_sum_ms_30s || 0) / s.cycle_time_count_30s)
    : null;
const maxCycleMs = (s.cycle_time_count_30s || 0) > 0
    ? Math.round(s.max_cycle_time_ms_30s || 0)
    : null;
const lastCompleteCycleAge = s.last_complete_cycle_ts
    ? Number(((now - s.last_complete_cycle_ts) / 1000).toFixed(3))
    : null;

const currentCycleSeen = Object.keys(s.live_cycle_seen)
    .map(Number)
    .filter(v => Number.isFinite(v) && v > 0)
    .sort((a, b) => a - b);
const currentCycleProgress = configuredBms > 0
    ? Number((currentCycleSeen.length / configuredBms).toFixed(2))
    : 0;
const currentCycleCompletedBms = currentCycleSeen.length;
const currentCycleSummary = configuredBms > 0
    ? `${currentCycleCompletedBms} / ${configuredBms} BMS completed`
    : "No configured BMS";

let currentCycleState = "idle_between_cycles";
if (Object.keys(s.pending).length > 0) {
    currentCycleState = "waiting_response";
} else if (currentCycleSeen.length > 0 && currentCycleSeen.length < configuredBms) {
    currentCycleState = "cycle_in_progress";
} else if (currentCycleSeen.length >= configuredBms && configuredBms > 0) {
    currentCycleState = "cycle_complete";
}

const lastPollAge = s.last_poll_ts ? Number(((now - s.last_poll_ts) / 1000).toFixed(3)) : null;
const lastResponseAge = s.last_response_ts ? Number(((now - s.last_response_ts) / 1000).toFixed(3)) : null;
const lastValidAge = s.last_valid_response_ts ? Number(((now - s.last_valid_response_ts) / 1000).toFixed(3)) : null;

const pendingEntries = Object.values(s.pending).sort((a, b) => Number(a.ts) - Number(b.ts));
let pollingState = "idle";
let currentTarget = "none";
if (pendingEntries.length > 0) {
    const p = pendingEntries[0];
    pollingState = "waiting_response";
    currentTarget = `BMS ${p.slave_id ?? "?"} / ${p.frame_type || "unknown"}`;
} else if (lastPollAge !== null && lastPollAge < 5) {
    pollingState = "running";
    currentTarget = `BMS ${s.last_poll_slave_id ?? "?"} / ${s.last_poll_frame_type || "unknown"}`;
} else if (lastPollAge === null || lastPollAge >= 30) {
    pollingState = "stopped";
}

const perBmsParts = [];
for (const id of configuredList) {
    const key = String(id);
    const sent = Number(s.polls_by_slave_30s[key]) || 0;
    const valid = Number(s.valid_by_slave_30s[key]) || 0;
    const tout = Number(s.timeouts_by_slave_30s[key]) || 0;
    const age = s.last_valid_by_slave[key]
        ? Number(((now - Number(s.last_valid_by_slave[key])) / 1000).toFixed(1))
        : null;
    perBmsParts.push(`BMS ${id}: ${valid}/${sent} valid, ${tout} timeout${tout === 1 ? "" : "s"}, age ${age === null ? "n/a" : age + " s"}`);
}
const perBmsSummary = perBmsParts.join(" | ");

const perBmsMarkdown = [];
for (const id of configuredList) {
    const key = String(id);
    const sent = Number(s.polls_by_slave_30s[key]) || 0;
    const valid = Number(s.valid_by_slave_30s[key]) || 0;
    const tout = Number(s.timeouts_by_slave_30s[key]) || 0;
    const age = s.last_valid_by_slave[key]
        ? Number(((now - Number(s.last_valid_by_slave[key])) / 1000).toFixed(1))
        : null;
    const ratio = sent > 0 ? valid / sent : 0;
    const seenRecently = Boolean(s.responding_seen[key]);
    let bmsState = "healthy";
    if (!seenRecently) bmsState = "missing";
    else if (tout > 0 || (sent >= 3 && ratio < 0.90)) bmsState = "degraded";

    const stateIcon = bmsState === "healthy" ? "✅" : (bmsState === "degraded" ? "⚠️" : "❌");
    perBmsMarkdown.push(
        `### ${stateIcon} BMS ${id}\n` +
        `**State:** \`${bmsState}\`  \n` +
        `**Success:** \`${sent > 0 ? Math.round(ratio * 100) : 0} %\`  \n` +
        `**Valid responses:** \`${valid}/${sent}\`  \n` +
        `**Timeouts:** \`${tout}\`  \n` +
        `**Last valid response:** \`${age === null ? "n/a" : age + " s ago"}\``
    );
}
const perBmsSummaryMarkdown = perBmsMarkdown.join("\n\n---\n\n");

const perBmsAttributes = {};
for (let id = 1; id <= 15; id++) {
    const key = String(id);
    const present = id <= configuredBms;
    const sent = Number(s.polls_by_slave_30s[key]) || 0;
    const valid = Number(s.valid_by_slave_30s[key]) || 0;
    const tout = Number(s.timeouts_by_slave_30s[key]) || 0;
    const age = s.last_valid_by_slave[key]
        ? Number(((now - Number(s.last_valid_by_slave[key])) / 1000).toFixed(1))
        : null;
    const ratio = sent > 0 ? valid / sent : 0;
    const seenRecently = Boolean(s.responding_seen[key]);

    let state = "not_configured";
    let indicator = "⚪";
    if (present) {
        state = "healthy";
        indicator = "🟢";
        if (!seenRecently) {
            state = "missing";
            indicator = "🔴";
        } else if (tout > 0 || (sent >= 3 && ratio < 0.90)) {
            state = "degraded";
            indicator = "🟠";
        }
    }

    perBmsAttributes[`per_bms_${id}_present`] = present ? "yes" : "no";
    perBmsAttributes[`per_bms_${id}_state`] = state;
    perBmsAttributes[`per_bms_${id}_indicator`] = indicator;
    perBmsAttributes[`per_bms_${id}_success_pct`] = sent > 0 ? Math.round(ratio * 100) : 0;
    perBmsAttributes[`per_bms_${id}_valid`] = valid;
    perBmsAttributes[`per_bms_${id}_sent`] = sent;
    perBmsAttributes[`per_bms_${id}_timeouts`] = tout;
    perBmsAttributes[`per_bms_${id}_last_valid_age_s`] = age;
}


const startup = (now - Number(s.first_ts || now)) < STARTUP_GRACE_MS;
let status = "starting";
let health_reason = "active_polling_starting";
let health_flags = [];

if (!startup) {
    if (pollsSent === 0 || lastPollAge === null || lastPollAge >= 30) {
        status = "no_communication";
        health_reason = "polling_stopped";
        health_flags.push("no_recent_polls");
    } else if (validResponses === 0 || lastValidAge === null || lastValidAge >= 30) {
        status = "no_communication";
        health_reason = "no_bms_response";
        health_flags.push("no_valid_responses");
    } else {
        status = "healthy";
        health_reason = "healthy_active_polling";

        if (missingList.length > 0) {
            status = "degraded";
            health_reason = missingList.length === 1 ? "one_bms_not_responding" : "multiple_bms_not_responding";
            health_flags.push("missing_bms");
        }

        if (pollsSent >= 5 && successRatio < 0.70) {
            status = "degraded";
            health_reason = "high_timeout_rate";
            health_flags.push("low_response_success_ratio");
        } else if (pollsSent >= 5 && successRatio < 0.90 && status === "healthy") {
            status = "degraded";
            health_reason = "partial_bms_response";
            health_flags.push("some_poll_failures");
        }

        if (invalidResponses > 0) health_flags.push("unvalidated_responses");
        if (timeouts > 0) health_flags.push("timeouts_seen");
        if (Object.keys(s.pending).length > configuredBms) health_flags.push("pending_queue_growing");

        // Response latency is transport-dependent and is therefore informational.
        // It does not degrade health by itself unless it produces timeouts or stale cycles.
        if (avgCycleMs !== null && lastCompleteCycleAge !== null && lastCompleteCycleAge > Math.max(30, (avgCycleMs / 1000) * 3)) {
            if (status === "healthy") status = "degraded";
            health_reason = "poll_cycle_stalled";
            health_flags.push("stale_complete_cycle");
        }
    }
}

const monitoringUptimeS = Math.max(0, Math.round((now - Number(s.first_ts || now)) / 1000));
const lastTimeoutAgeS = s.last_timeout_ts
    ? Number(((now - s.last_timeout_ts) / 1000).toFixed(1))
    : null;
const noTimeoutDurationS = Math.max(
    0,
    Math.round((now - (s.last_timeout_ts || Number(s.first_ts || now))) / 1000)
);

// Synthetic score: useful for support, but detailed reason/flags remain authoritative.
let healthScore = null;
let healthScoreLabel = "starting";
if (!startup) {
    healthScore = 100;

    if (configuredBms > 0) {
        healthScore -= Math.round((missingList.length / configuredBms) * 50);
    }
    if (pollsSent > 0) {
        healthScore -= Math.round(Math.max(0, 1 - successRatio) * 40);
    }

    healthScore -= Math.min(10, timeouts * 2);
    healthScore -= Math.min(10, invalidResponses * 2);

    if (Object.keys(s.pending).length > configuredBms) healthScore -= 10;
    if (health_flags.includes("stale_complete_cycle")) healthScore -= 20;
    if (status === "no_communication") healthScore = Math.min(healthScore, 20);

    healthScore = Math.max(0, Math.min(100, Math.round(healthScore)));

    if (healthScore >= 95) healthScoreLabel = "excellent";
    else if (healthScore >= 90) healthScoreLabel = "good";
    else if (healthScore >= 70) healthScoreLabel = "degraded";
    else healthScoreLabel = "critical";
}

function buildScoreDetail() {
    const parts = [];

    if (missingList.length > 0) {
        parts.push(`${missingList.length} configured BMS missing`);
    }
    if (pollsSent > 0 && successRatio < 1) {
        parts.push(`${Math.round((1 - successRatio) * 100)}% unsuccessful transactions`);
    }
    if (timeouts > 0) {
        parts.push(`${timeouts} timeout${timeouts === 1 ? "" : "s"} in the 30 s window`);
    }
    if (invalidResponses > 0) {
        parts.push(`${invalidResponses} unvalidated response${invalidResponses === 1 ? "" : "s"} in the 30 s window`);
    }
    if (Object.keys(s.pending).length > configuredBms) {
        parts.push(`${Object.keys(s.pending).length} pending transactions`);
    }
    if (health_flags.includes("stale_complete_cycle")) {
        parts.push("complete polling cycle became stale");
    }

    if (!parts.length && healthScore !== null && healthScore < 100) {
        parts.push("minor transient penalty while communication remained healthy");
    }
    if (!parts.length) {
        parts.push("no communication fault detected");
    }

    return parts.join("; ");
}

const currentScoreDetail = buildScoreDetail();

// Persistent worst-state memory since diagnostic start.
if (healthScore !== null) {
    if (s.worst_health_score === null) {
        s.worst_health_score = healthScore;
        s.worst_health_reason = health_reason;
        s.worst_health_flags_text = health_flags.length ? health_flags.join(", ") : "none";
        s.worst_score_detail = currentScoreDetail;
        s.worst_health_ts = now;
    } else if (healthScore < s.worst_health_score) {
        s.worst_health_score = healthScore;
        s.worst_health_reason = health_reason;
        s.worst_health_flags_text = health_flags.length ? health_flags.join(", ") : "none";
        s.worst_score_detail = currentScoreDetail;
        s.worst_health_ts = now;
    } else if (
        healthScore === s.worst_health_score &&
        status !== "healthy" &&
        health_reason !== s.worst_health_reason
    ) {
        s.worst_health_reason = health_reason;
        s.worst_health_flags_text = health_flags.length ? health_flags.join(", ") : "none";
        s.worst_score_detail = currentScoreDetail;
        s.worst_health_ts = now;
    }
}

const previousWasHealthy = ["healthy", "starting"].includes(s.previous_health_status);
const currentIsIncident = !["healthy", "starting"].includes(status);
if (previousWasHealthy && currentIsIncident) {
    s.health_incident_count += 1;
}
s.previous_health_status = status;

const worstHealthAgeS = s.worst_health_ts
    ? Number(((now - s.worst_health_ts) / 1000).toFixed(1))
    : null;

const transport = global.get("use_gateway") === true ? "tcp" : "serial";
const health_flags_text = health_flags.length ? health_flags.join(", ") : "none";
const healthReasonText = humanReason(health_reason);
const worstHealthReasonText = humanReason(s.worst_health_reason || health_reason);
const monitoringUptimeHuman = formatDuration(monitoringUptimeS);
const noTimeoutDurationHuman = formatDuration(noTimeoutDurationS);

msg.topic = "BMS_GLOBAL/health";
msg.payload = {
    status,
    health_reason,
    health_reason_text: healthReasonText,
    health_flags,
    health_flags_text,
    mode: "active_polling",
    transport,

    configured_bms: configuredBms,
    configured_bms_list: configuredList.join(", "),
    responding_bms: respondingList.length,
    responding_bms_list: respondingList.join(", "),
    missing_bms: missingList.length,
    missing_bms_list: missingList.join(", "),
    per_bms_summary: perBmsSummary,
    per_bms_summary_markdown: perBmsSummaryMarkdown,
    ...perBmsAttributes,

    health_score: healthScore,
    health_score_label: healthScoreLabel,
