    node.debug(`Discovery déjà envoyé pour BMS ${slaveIdStr}`);
}

for (var t in topics) {
    outputMsgs.push({
        topic: t,
        payload: topics[t]
    });
}


// === JK-BMS Legacy 4.1.12-alpha1: DRY LIVE read-only ===
// No SETUP write; never republish a state if the incoming byte is unavailable.
if (Number.isInteger(legacyDryLiveRaw) && legacyDryLiveRaw >= 0 && legacyDryLiveRaw <= 255) {
    const dryDefinitions = [{ index: 1, mask: 0x02 }, { index: 2, mask: 0x04 }];
    for (const dry of dryDefinitions) {
        const suffix = `dry${dry.index}_contact`;
        const objectId = `${baseTopic.toLowerCase()}_${suffix}`;
        const stateTopic = `${baseTopic}/state/${suffix}`;
        outputMsgs.push({topic: stateTopic, payload: (legacyDryLiveRaw & dry.mask) ? "ON" : "OFF"});
        const sentKey = `legacy_dry_live_discovery_${deviceID}_${dry.index}`;
        if (!discoveryAlreadySent || !flow.get(sentKey)) {
            const discovery = {
                name: `DRY${dry.index} contact`,
                unique_id: `${deviceID}_${suffix}_legacy_v4`,
                object_id: objectId,
                default_entity_id: `binary_sensor.${objectId}`,
                state_topic: stateTopic,
                payload_on: "ON", payload_off: "OFF",
                icon: "mdi:electric-switch",
                entity_category: "diagnostic",
                device: {identifiers: [deviceID], name: deviceName,
                    manufacturer: "Smartphoton-JK-BMS / ©JLM 2025-2026", model: "JK-BMS RS485"}
