            buf[i + 1] === 0xAA &&
            buf[i + 2] === 0xEB &&
            buf[i + 3] === 0x90
        ) {
            headerCount++;
        }

        // début plausible Modbus
        if (
            i < buf.length - 4 &&
            buf[i] >= 0x01 && buf[i] <= 0x0F &&
            buf[i + 1] === 0x10 &&
            buf[i + 2] === 0x16 &&
            (buf[i + 3] === 0x20 || buf[i + 3] === 0x1E)
        ) {
            headerCount++;
        }
    }

    if (headerCount > 0) {
        s.frame_candidates_30s += 1;
    }
    if (headerCount > 1) {
        s.multi_header_buffers_30s += 1;
    }
}

