// Remise à zéro des flags utilisés par Setup To MQTT.
// nb_jkbms = nombre TOTAL de JK-BMS configurés.
let totalBms = parseInt(global.get("nb_jkbms"), 10);

if (isNaN(totalBms) || totalBms < 1) {
    totalBms = 1;
}

const broadcasting =
    global.get("bms_broadcasting") === true ||
    global.get("bms_broadcasting") === "true" ||
    global.get("bms_broadcasting") === 1 ||
    global.get("bms_broadcasting") === "1";

function getSlaveAddressesToReset() {
    // En Broadcasting, le Master adresse 0 fait partie du total.
    // ISSUE #180: utiliser les adresses réellement vues dans SETUP pour rester
    // compatible avec Master+BMS_1, Master+BMS_2 et les adresses non consécutives.
    if (broadcasting) {
        const neededSlaves = Math.max(0, totalBms - 1);
        if (neededSlaves === 0) return { addresses: [], detected: true };

        const now = Date.now();
        const MAX_AGE_MS = 120 * 1000;
        const seen = global.get("premium.dashboard_bms_seen");

        if (seen && typeof seen === "object" && !Array.isArray(seen)) {
            const candidates = Object.entries(seen)
                .filter(([id, ts]) => {
                    const n = Number(id);
                    const t = Number(ts);
                    return id !== "master" &&
                        Number.isInteger(n) && n >= 1 && n <= 15 &&
                        Number.isFinite(t) && (now - t) <= MAX_AGE_MS;
                })
                .map(([id, ts]) => ({ address: Number(id), ts: Number(ts) }))
                .sort((a, b) => b.ts - a.ts);

            if (candidates.length >= neededSlaves) {
                const addresses = candidates
                    .slice(0, neededSlaves)
                    .map(x => x.address)
                    .sort((a, b) => a - b);
                return { addresses, detected: true };
            }
        }

        // Fallback conservateur = ancien comportement.
        // Cela évite de casser une ancienne installation si les SETUP n'ont
        // pas encore été reçus au moment du reset.
        return {
            addresses: Array.from({ length: totalBms }, (_, i) => i + 1),
            detected: false
        };
    }

    // Hors Broadcasting: BMS_1 ... BMS_N.
    return {
        addresses: Array.from({ length: totalBms }, (_, i) => i + 1),
        detected: true
    };
}

