        8: "Discharge overtemp",
        9: "Charge undertemp",
        10: "Discharge undertemp",
        11: "MOS overtemp",
        12: "Short circuit",
        13: "BMS overtemp",
        14: "BMS undertemp",
        23: "Cell imbalance",
        35: "System normal"
    };
    return {
        type: "cycle_count",
        alarmCode,
        alarmText: alarmMap[alarmCode] || `Unknown alarm ${alarmCode}`,
        cycleCount
    };
}

function decode1806E5F4(data) {
    const value = (data[3] << 8) | data[2];
    return {
        type: "status_data",
        value,
        byte0: data[0],
        byte1: data[1],
        rawBytes: data
    };
}

function decode18F228F4(data) {
    const temps = [];
    let mosTemp = null;
    for (let i = 1; i < 6; i++) {
        if (data[i] !== 0) {
            const temp = data[i] - 50;
            temps.push(temp);
        }
    }
    if (temps.length > 0) {
        mosTemp = temps[0];
    }
    return {
        type: "individual_temps",
        temperatures: temps,
        mosTemp,
        sensorCount: temps.length,
        byte0: data[0]
    };
}

function decode18F428F4(data) {
    const systemData = (data[1] << 8) | data[0];
    const socAlt = data[6];
    return {
        type: "alt_soc_data",
        systemData,
        socAlt,
        byte2: data[2],
        rawBytes: data
    };
}

function decodeCellVoltages(canId, data) {
    const baseId = parseInt(canId.substring(3, 4));
    const cellStart = baseId * 4;
    const voltages = [];
    for (let i = 0; i < 8; i += 2) {
        const voltage = ((data[i + 1] << 8) | data[i]) * 0.001;
        voltages.push({
            cellNumber: cellStart + (i / 2) + 1,
            voltage
        });
    }
    return {
        type: "cell_voltages",
        group: baseId,
        voltages
    };
}

function decodeExperimental(canId, data) {
    const patterns = [];
    for (let i = 0; i < data.length; i++) {
        if (data[i] >= 70 && data[i] <= 80) {
            patterns.push({
                type: "possible_mos_temp",
                position: i,
                value: data[i] - 50,
                rawValue: data[i]
            });
        }
    }
    for (let i = 0; i < data.length - 1; i++) {
        const value16 = (data[i + 1] << 8) | data[i];
        if (value16 >= 10 && value16 <= 50) {
            patterns.push({
                type: "possible_cycle_count",
                position: i,
                value: value16,
                rawBytes: [data[i], data[i + 1]]
            });
        }
    }
    return {
        type: "experimental",
        canId,
        patterns,
        rawData: data
    };
}

