// nb_jkbms = nombre TOTAL de batteries
const totalCount = Math.max(1, Number(global.get("nb_jkbms")) || 1);

function getDetectedBroadcastSuffixes() {
    if (!hasMaster) return null;

    const now = Date.now();
    const MAX_AGE_MS = 120 * 1000;
    const neededSlaves = Math.max(0, totalCount - 1);
    const seen = global.get("premium.dashboard_bms_seen");

    if (!seen || typeof seen !== "object" || Array.isArray(seen)) return null;

    const masterTs = Number(seen.master);
    if (!Number.isFinite(masterTs) || (now - masterTs) > MAX_AGE_MS) return null;

    const candidates = Object.entries(seen)
        .filter(([id, ts]) => {
            const n = Number(id);
            const t = Number(ts);
            return id !== "master" && Number.isInteger(n) && n >= 1 && n <= 15 &&
                Number.isFinite(t) && (now - t) <= MAX_AGE_MS;
        })
        .map(([id, ts]) => ({ id: String(Number(id)), ts: Number(ts) }));

    // If more identifiers are temporarily present after an address change,
    // prefer the identifiers seen most recently, then display them by address.
    candidates.sort((a, b) => b.ts - a.ts);
    if (candidates.length < neededSlaves) return null;

    return candidates
        .slice(0, neededSlaves)
        .sort((a, b) => Number(a.id) - Number(b.id))
        .map(x => x.id);
}

