    return slot.entitySuffix === "master" ? "Master" : `JK-BMS ${slot.entitySuffix}`;
}

function titleEntityText(slot) {
    return slot.entitySuffix === "master" ? "BMS_master" : `BMS_${slot.entitySuffix}`;
}

function btnBadge(name, navPath, bg, color = "white") {
    return {
        type: "custom:button-card",
        name,
        tap_action: {
            action: "navigate",
            navigation_path: navPath
        },
        styles: {
            card: [
                { color },
                { "background-color": bg },
                { "border-radius": "10px" },
                { padding: "10px" },
                { margin: "10px" }
            ]
        },
        layout_options: {
            grid_columns: 1,
            grid_rows: 1
        }
    };
}

function entityCard(entity, name, extra = {}) {
    return Object.assign({
        type: "custom:mushroom-entity-card",
        entity,
        name,
        fill_container: true
    }, extra);
}

function gaugeCard(entity, name, min, max, green, yellow, red, unit) {
    return {
        type: "gauge",
        entity,
        needle: true,
        severity: { green, yellow, red },
        name,
        unit,
        theme: "ios-dark-mode-blue-red-alternative",
        grid_options: {
            columns: 4,
            rows: "auto"
        },
        max,
        min
    };
}

function binarySwitchTemplate(entity, primary) {
    return {
        type: "custom:mushroom-template-card",
        entity,
        primary,
        secondary: "{{ 'On' if is_state(entity, 'on') else 'Off' if is_state(entity, 'off') else 'Unknown' }}",
        icon: "{{ 'mdi:toggle-switch' if is_state(entity, 'on') else 'mdi:toggle-switch-off' if is_state(entity, 'off') else 'mdi:help-circle' }}",
        icon_color: "{{ 'green' if is_state(entity, 'on') else 'red' if is_state(entity, 'off') else 'grey' }}",
        grid_options: {
            columns: 4,
            rows: 1
        },
        tap_action: {
            action: "more-info"
        }
    };
}

function customCardsWarningCard() {
    const isFr = dashboardLanguage.startsWith("fr");

    return {
        type: "markdown",
        content: isFr
            ? `# ⚠️ Dashboard non optimal

Pour un affichage optimal, il faut :

- installer les cartes personnalisées :
  - Mushroom
  - Entity Progress Card
  - Button Card
  - Stack-in-card
  - Bar Card
- cocher l’option correspondante dans la configuration du module
- redémarrer le module

Sans cela, certaines cartes du dashboard premium peuvent être incomplètes ou non affichées.`
            : `# ⚠️ Non-optimal dashboard

For the best display, you need to:

- install the custom cards:
  - Mushroom
  - Entity Progress Card
  - Button Card
  - Stack-in-card
  - Bar Card
- enable the corresponding option in the module configuration
- restart the module

Otherwise, some premium dashboard cards may be incomplete or not displayed.`
    };
}

