function stackCard(content) {
    return {
        type: "custom:stack-in-card",
        keep: {
            margin: false,
            box_shadow: false,
            background: true
        },
        card_mod: {
            style: `
                ha-card {
                    box-shadow: none;
                    background: #021017;
                    border: black solid 1px !important;
                }
                .card-content {
                    padding: 8px;
                }
            `
        },
        cards: [
            {
                type: "markdown",
                content
            }
        ],
        grid_options: {
            columns: 12,
            rows: "auto"
        }
    };
}

