function readAddonOptionsFile() {
    // Lecture directe des options add-on.
    // Important : les anciens dashboards lisent souvent bms_broadcasting depuis le contexte,
    // mais le dashboard HTML doit aussi pouvoir lire /data/options.json au moment de la génération.
    const fsCtx =
        (typeof fs !== "undefined" && fs && typeof fs.readFileSync === "function")
            ? fs
            : global.get("fs");

    if (!fsCtx || typeof fsCtx.readFileSync !== "function") return {};

    const paths = [
        "/data/options.json",
        "/addon/options.json",
        "/config/options.json"
    ];

    for (const p of paths) {
        try {
            if (fsCtx.existsSync && !fsCtx.existsSync(p)) continue;
            const raw = fsCtx.readFileSync(p, "utf8");
            const obj = JSON.parse(raw);
            if (obj && typeof obj === "object") return obj;
        } catch (_) {}
    }

    return {};
}
const addonOptionsFile = readAddonOptionsFile();

