/* ===== JK-BMS V2 VISUEL ===== */
.bms-wall{
  display:grid;
  grid-template-columns:repeat(2,minmax(420px,1fr));
  gap:14px;
}
.bms-pack{
  position:relative;
  overflow:hidden;
  background:
    radial-gradient(circle at 15% 0%,rgba(36,224,109,.18),transparent 32%),
    radial-gradient(circle at 90% 10%,rgba(46,199,255,.12),transparent 36%),
    linear-gradient(180deg,rgba(14,27,50,.98),rgba(5,12,25,.96));
  border:1px solid rgba(126,161,206,.22);
  border-radius:22px;
  padding:14px;
  box-shadow:0 20px 60px rgba(0,0,0,.34);
}
.bms-pack:before{
  content:"";
  position:absolute;
  inset:0;
  background-image:
    linear-gradient(rgba(126,161,206,.045) 1px,transparent 1px),
    linear-gradient(90deg,rgba(126,161,206,.045) 1px,transparent 1px);
  background-size:28px 28px;
  pointer-events:none;
}
.bms-head{
  position:relative;
  z-index:1;
  display:flex;
  align-items:center;
  justify-content:space-between;
  margin-bottom:14px;
}
.bms-title{
  display:flex;
  align-items:center;
  gap:10px;
  font-size:22px;
  font-weight:1000;
  letter-spacing:-.6px;
}
.bms-title-icon{
  width:38px;
  height:38px;
  border-radius:12px;
  display:flex;
  align-items:center;
  justify-content:center;
  background:rgba(36,224,109,.16);
  border:1px solid rgba(36,224,109,.35);
  box-shadow:0 0 24px rgba(36,224,109,.12);
}
.bms-pill{
  padding:7px 11px;
  border-radius:999px;
  background:rgba(36,224,109,.13);
  border:1px solid rgba(36,224,109,.38);
  color:#baffcf;
  font-size:12px;
  font-weight:900;
}
.bms-body{
  position:relative;
  z-index:1;
  display:grid;
  grid-template-columns:185px 1fr;
  gap:14px;
  align-items:center;
}
.soc-ring{
  width:170px;
  height:170px;
  border-radius:50%;
  display:flex;
  align-items:center;
  justify-content:center;
  background:conic-gradient(var(--bat) 0 75%,#182335 75% 100%);
  box-shadow:0 0 45px rgba(36,224,109,.16);
}
.soc-ring-inner{
  width:113px;
  height:113px;
  border-radius:50%;
  background:#0b1424;
  display:flex;
  align-items:center;
  justify-content:center;
  text-align:center;
  border:1px solid rgba(126,161,206,.16);
}
.soc-ring-inner .value{
  font-size:33px;
}
.bms-main-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:9px;
}
.bms-kpi{
  background:rgba(9,18,34,.76);
  border:1px solid rgba(126,161,206,.16);
  border-radius:15px;
  padding:10px;
  min-height:82px;
}
.bms-kpi .label{font-size:10px}
.bms-kpi .value{font-size:23px}
.bms-kpi .small{font-size:11px}
.sv-scale-bar{position:relative;height:8px;border-radius:999px;background:rgba(30,41,59,.95);overflow:hidden;margin-top:8px;border:1px solid rgba(126,161,206,.14)}
.sv-scale-fill{position:absolute;top:0;bottom:0;border-radius:999px;background:linear-gradient(90deg,rgba(34,197,94,.85),rgba(46,199,255,.85));box-shadow:0 0 14px rgba(46,199,255,.22)}
.sv-scale-zero{position:absolute;top:-2px;bottom:-2px;width:2px;background:rgba(255,255,255,.42);box-shadow:0 0 8px rgba(255,255,255,.25)}
.sv-soc-wrap{display:grid;gap:8px;justify-items:center}
.sv-soc-wrap .sv-scale-bar{width:155px;max-width:90%;margin-top:0}
.bms-positive{border-color:rgba(36,224,109,.42)}
.bms-negative{border-color:rgba(255,95,122,.42)}
.bms-warn{border-color:rgba(255,159,67,.44)}
.bms-blue{border-color:rgba(46,199,255,.42)}
.bms-cells{
  position:relative;
  z-index:1;
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:8px;
  margin-top:12px;
}
.cell-card{
  background:rgba(9,18,34,.72);
  border:1px solid rgba(126,161,206,.14);
  border-radius:14px;
  padding:9px;
}
.cell-card .value{font-size:21px}
.bms-temp-strip{
  position:relative;
  z-index:1;
  display:grid;
  grid-template-columns:repeat(5,1fr);
  gap:8px;
  margin-top:10px;
}
.temp-chip{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:6px;
  background:rgba(255,159,67,.09);
  border:1px solid rgba(255,159,67,.25);
  border-radius:12px;
  padding:8px 9px;
  font-weight:900;
}
.temp-chip span{
  color:var(--muted);
  font-size:11px;
  text-transform:uppercase;
  letter-spacing:.5px;
}
.temp-chip b{
  font-size:15px;
}
.bms-alert{
  position:relative;
  z-index:1;
  margin-top:10px;
  padding:9px 10px;
  border-radius:13px;
  background:rgba(46,199,255,.08);
  border:1px solid rgba(46,199,255,.20);
  color:#cfeeff;
  font-size:12px;
  display:flex;
  justify-content:space-between;
  gap:10px;
}
@media(max-width:1200px){
  .bms-wall,.bms-body,.bms-main-grid,.bms-cells,.bms-temp-strip{grid-template-columns:1fr}
  .soc-ring{margin:auto}
}

@media(max-width:1200px){.bms-top,.bms-metrics,.cell-grid,.temp-grid{grid-template-columns:1fr}.soc-ring{width:150px;height:150px}}

@media(max-width:1200px){.shell,.dash-grid,.energy-area,.cards4,.cards5,.cards3,.cards2,.donut-row,.gauge-row{grid-template-columns:1fr}.sidebar{min-height:auto}.flowbox{height:auto;min-height:900px;padding:12px}.node,.mppt,.solar-total,.n-grid,.n-load,.n-bat,.inverter-core{position:relative;left:auto;right:auto;top:auto;bottom:auto;transform:none;width:auto;margin:10px}svg.flow{display:none}}


