}
function buildArchiveSeries(period,count){
  const arr=archiveArr(period), map={};
  arr.forEach(it=>{if(it?.key)map[String(it.key)]=it});
  const now=new Date(), out=[];
  for(let i=count-1;i>=0;i--){
    let d,key,label;
    if(period==='daily'){d=new Date(now);d.setHours(0,0,0,0);d.setDate(d.getDate()-i);key=dayKey(d);label=pad(d.getDate())+'/'+pad(d.getMonth()+1)}
    else if(period==='monthly'){d=new Date(now.getFullYear(),now.getMonth()-i,1);key=monthKey(d);label=pad(d.getMonth()+1)+'/'+String(d.getFullYear()).slice(2)}
    else{d=new Date(now.getFullYear()-i,0,1);key=yearKey(d);label=key}
    const it=map[key]||{};
    let solar=archiveValue(it,'solar'), battery=archiveValue(it,'battery'), total=archiveValue(it,'total');
    const live=liveEcoFallback(period,key);
    if(live && (!total || total<=0)){solar=live.solar;battery=live.battery;total=live.total}
    out.push({key,label,solar,battery,total:Math.max(0,total || (solar+battery))});
  }
  return out;
}
