function bmsRead(entity,def='--'){const st=STATES[entity]; return st&&!bad(st.state)?String(st.state):def}
function firstExisting(ids,fallback){return ids.find(id=>STATES[id]) || fallback}
function getNumberFromEntity(id){const st=STATES[id];if(!st||bad(st.state))return NaN;const x=Number(String(st.state).replace(',', '.'));return Number.isFinite(x)?x:NaN}
function bmsHasMeaningfulData(i){
  const soc=bmsNum(i,'soc_pourcentage');
  const volt=bmsNum(i,'tension_totale_volt');
  const power=Math.abs(bmsNum(i,'puissance_totale'));
  const current=Math.abs(bmsNum(i,'courant_total'));
  const avg=bmsNum(i,'cell_voltage_average');
  const delta=Math.abs(bmsNum(i,'cell_voltage_delta'));
  return (Number.isFinite(soc)&&soc>0) ||
         (Number.isFinite(volt)&&volt>10) ||
         (Number.isFinite(avg)&&avg>2) ||
         power>1 ||
         current>0.1 ||
         delta>0.0001;
}
function detectBroadcastingMode(){
  if(BMS_BROADCASTING_FROM_CONFIG===true || BMS_BROADCASTING===true)return true;
  const all=Object.keys(STATES||{});
  if(all.some(id=>/^(?:sensor|binary_sensor|number|switch)\.bms_master_/i.test(id)))return true;
  function directCandidates(key, slug){
    const ids=[];
    bmsSlugList(slug).forEach(s=>{
      ids.push('sensor.bms_'+key+'_bms_'+s);
      ids.push('sensor.bms_'+key+'_'+s);
      ids.push('sensor.bms_'+key+'_bms_'+key+'_'+s);
    });
    return ids;
  }
  function directNum(key, slug){const v=n(state(directCandidates(key,slug),0));return Number.isFinite(v)?v:0;}
  function directHasData(key){
    return directNum(key,'soc_pourcentage')>0.5 || directNum(key,'tension_totale_volt')>10 || Math.abs(directNum(key,'puissance_totale'))>1 || Math.abs(directNum(key,'courant_total'))>0.1 || directNum(key,'cell_voltage_average')>2 || Math.abs(directNum(key,'cell_voltage_delta'))>0.0001 || directNum(key,'soh_pourcentage')>0.5 || directNum(key,'mos_temp')>1;
  }
  let after=0; for(let k=2;k<=31;k++){if(directHasData(k))after++;}
  return !directHasData(1)&&after>=1;
}function refreshBroadcastingMode(){BMS_BROADCASTING=detectBroadcastingMode();return BMS_BROADCASTING}
function bmsSensorEntity(i,slug){return firstExisting(bmsEntityCandidates(i,slug,'sensor'),`sensor.bms_${i}_bms_${slug}`)}
function bmsNumberEntity(i,slug){return firstExisting(bmsEntityCandidates(i,slug,'number'),`number.bms_${i}_bms_${slug}`)}
function bmsSwitchEntity(i,slug){return firstExisting(bmsEntityCandidates(i,slug,'switch'),`switch.bms_${i}_bms_${slug}`)}
