function alarmValueActive(v){
  const s=String(v ?? '').trim().toLowerCase();
  if(!s||['off','false','0','ok','none','aucune','normal','clear','cleared','inactive','not active','unavailable','unknown','--'].includes(s))return false;
  if(s.includes('no alarm')||s.includes('aucune')||s.includes('inactive')||s.includes('not active'))return false;
  if(['on','true','1','alarm','alarme','warning','warn','fault','error','detected'].includes(s))return true;
  return /\b(alarm|alarme|warning|warn|fault|error|detected)\b/.test(s);
}
function bmsAlarmActive(i){
  const ids=[
