    `binary_sensor.bms_${i}_alarm_active`,
    `sensor.bms_${i}_bms_alarm_status`,
    `sensor.bms_${i}_bms_alarm_list`,
    `sensor.bms_${i}_bms_visual_status`,
    `sensor.bms_${i}_bms_${i}_alarm_status`,
    `sensor.bms_${i}_bms_${i}_alarm_list`,
    `sensor.bms_${i}_bms_${i}_visual_status`,
    `sensor.bms_${i}_alarm_status`,
    `sensor.bms_${i}_alarm_list`,
    `sensor.bms_${i}_visual_status`
