  const txt=v=>String(v??'').trim();
  const low=v=>txt(v).toLowerCase();
  const isMissing=v=>{const l=low(v);return !l||['--','unknown','unavailable','null','undefined'].includes(l)};
  const numberFrom=v=>{const n=parseFloat(txt(v).replace(',','.'));return Number.isFinite(n)?n:null};
  const stateNumber=id=>{const st=state(id);if(!st||isMissing(st.state))return null;return numberFrom(st.state)};
  const stateText=id=>{const st=state(id);return st&&!isMissing(st.state)?txt(st.state):''};
  const textNumber=id=>{const el=$(id);const n=numberFrom(el?.textContent);return n===null?null:n};
  const exactNumber=id=>stateNumber(id);
  function batteryPowerValue(){const v=exactNumber('sensor.voltronic_global_battery_power');if(v!==null)return v;const kw=textNumber('bat_kw');return kw!==null?kw*1000:null}
  function batteryCurrentValue(){const v=exactNumber('sensor.voltronic_global_battery_global_current');if(v!==null)return v;const p=batteryPowerValue(),bv=calcBatV();return p!==null&&bv?Math.abs(p/bv):null}
  function findWarnEntity(i){
