    for(const id of direct){if(state(id))return id}
    const ids=Object.keys(states());
    return ids.find(id=>{
      const h=hay(id);
      return id.startsWith('sensor.') && h.includes('voltronic') && (h.includes(`inv${i}`)||h.includes(`inverter ${i}`)||h.includes(`inverter_${i}`)||h.includes(`inverter ${String(i).padStart(2,'0')}`)) && (h.includes('warning state')||h.includes('warn state')||h.includes('diag warn'));
    }) || direct[0];
  }
  function directWarnStatus(i){
