  function hay(id){const st=state(id)||{},a=st.attributes||{};return low([id,a.friendly_name,a.device_class,a.status,a.message,a.detail,a.details,a.description,st.state].filter(Boolean).join(' '))}
  function findEntity(candidates,wordSets,domain){for(const id of candidates){if(state(id))return id}const ids=Object.keys(states());for(const words of wordSets){const hit=ids.find(id=>(!domain||id.startsWith(domain+'.'))&&words.every(w=>hay(id).includes(low(w))));if(hit)return hit}return candidates[0]}
  function first(ids,wordSets=[],domain){return findEntity(ids,wordSets,domain)}
  function firstNumber(ids,wordSets=[],domain){const ent=findEntity(ids,wordSets,domain);const v=stateNumber(ent);if(v!==null)return v;for(const id of ids){const n=stateNumber(id);if(n!==null)return n}return null}
  function invIds(){try{return getInverterIds()}catch(e){return[1,2]}}
