    batPower:()=> 'sensor.voltronic_global_battery_power',
    batV:()=>first(['sensor.voltronic_global_battery_voltage'],[['voltronic','global','battery','voltage']],'sensor'),
    batA:()=> 'sensor.voltronic_global_battery_global_current',
    chargeW:()=>first(['sensor.voltronic_global_battery_charge_power','sensor.voltronic_global_battery_charge','sensor.voltronic_global_battery_power'],[['voltronic','global','battery','charge','power']],'sensor'),
    disW:()=>first(['sensor.voltronic_global_battery_discharge_power','sensor.voltronic_global_battery_discharge','sensor.voltronic_global_battery_power'],[['voltronic','global','battery','discharge','power']],'sensor'),
