  };
  function tempInvValue(i){const direct=stateNumber(`sensor.voltronic_inv${i}_inverter_heat_sink_temp`);if(direct!==null)return direct;if(typeof tempInv==='function'){const v=numberFrom(tempInv(i));if(v!==null&&v!==0)return v}return firstNumber([`sensor.voltronic_inv${i}_heat_sink_temperature`,`sensor.voltronic_inv${i}_inverter_temperature`,`sensor.voltronic_inv${i}_internal_temperature`,`sensor.voltronic_inv${i}_q1_internal_temperature`],[['voltronic','inv'+i,'heat','sink'],['voltronic','inverter',String(i),'temperature']],'sensor')}
  function bmsTempEntity(){const preferred=['sensor.bms_1_bms_sonde_1_temp','sensor.bms_1_bms_sonde_2_temp','sensor.bms_1_bms_mos_temp','sensor.bms_1_sonde_1_temp','sensor.bms_1_sonde_2_temp','sensor.bms_1_mos_temp','sensor.bms_1_bms_temperature','sensor.bms_1_temperature','sensor.bms_1_temp','sensor.bms_1_temperature_1'];for(const id of preferred){if(state(id))return id}return Object.keys(states()).find(id=>id.startsWith('sensor.bms_1')&&id.toLowerCase().includes('temp')&&!/min|max|limit|protect|warning|alarm|delta|diff/.test(id.toLowerCase()))||preferred[0]}
  function bmsTempValue(){
    const vals=[];
    for(const id of Object.keys(states())){
      const l=id.toLowerCase();
      if(id.startsWith('sensor.bms_')&&l.includes('temp')&&!/min|max|limit|protect|warning|alarm|delta|diff/.test(l)){
        const v=stateNumber(id);if(v!==null)vals.push(v);
      }
    }
    if(vals.length)return vals.reduce((a,b)=>a+b,0)/vals.length;
    if(typeof v27BmsTempAvg==='function'){const v=numberFrom(v27BmsTempAvg());if(v!==null&&v!==0)return v}
    return null
  }
  function val(id,fmt,keep){const v=stateNumber(id);return v===null?keep:fmt(v)}
  function calcCharge(){try{return globalNum(E.charge,()=>sumInv('battery_charge'))}catch(e){const v=stateNumber(ent.chargeW());return v!==null?v:0}}
  function calcDischarge(){try{return globalNum(E.discharge,()=>sumInv('battery_discharge'))}catch(e){const v=stateNumber(ent.disW());return v!==null?v:0}}
  function calcBatV(){try{return globalNum(E.battV,()=>avgInv('battery_voltage'))}catch(e){const v=stateNumber(ent.batV());return v!==null?v:0}}
  function calcBatA(){const v=batteryCurrentValue();return v===null?0:v}
  function signedPower(kind,keep){const p=batteryPowerValue();return p===null?keep:String(Math.round(Math.abs(p)))}
