      const overview=ev.target.closest&&ev.target.closest('#jkbms [data-bms-overview="1"]');
      if(overview){ev.preventDefault();ev.stopImmediatePropagation();setBmsView('overview');return;}
      const pack=ev.target.closest&&ev.target.closest('#jkbms .bms-pack.clickable');
      if(pack){
        if(ev.target.closest('[data-hist]'))return;
        const raw=String(pack.dataset.bmsCard||'');const packs=[...document.querySelectorAll('#jkbms .bms-pack.clickable')];const i=raw||String(packs.indexOf(pack)+1);if(i){ev.preventDefault();ev.stopImmediatePropagation();setBmsView('battery',i)}
