    if(nav){const [k,i]=nav.dataset.nav.split(':');ev.preventDefault();ev.stopPropagation();if(k==='inv')openInv(Number(i));else openBms(i);return}
  },true);
  const old=window.update;window.update=function(){if(typeof old==='function')old.apply(this,arguments);try{renderPieuvre();updateAlarms();paintMixDonut();decorateValueIcons();decorateBmsIcons();decorateBmsAlarms();decorateBmsSocRings()}catch(e){console.warn('clean mods',e)}};
