  if(frame && frame.dataset.moduleId===targetModule.id){
    targetButton.classList.add('active');
    setActiveId(targetModule.id);
    return;
  }

  setTimeout(()=>open(targetModule,targetButton),0);
}

scan();
setInterval(scan,15000);
})();
