repairFlatHistoryWithLive(k,entity,series){const vals=(series||[]).map(p=>Number(p[1])).filter(Number.isFinite);const live=liveNumberForHistory(k,entity);if(live!==null&&Math.abs(live)>1&&vals.length&&Math.max(...vals.map(Math.abs))<=1)return liveFallbackSeries(k,entity);return series}\nasync function configuredHistory(k,mode,title){\n  const list=customEntityListForKey(k);\n  const all=[];\n  for(const id of list){const serie=normalizeHistorySeriesForKey(k,id,await fetchHaHistory(id));if(serie.length>1)all.push(serie)}\n  let series=mode==='avg'?averageHistorySeries(all):sumHistorySeries(all);\n  const local=localHistory(k,list[0]||null);\n  if(series.length<2&&local.length>1)series=local;\n  if(series.length<2)series=liveFallbackSeries(k,null);\n  series=repairFlatHistoryWithLive(k,null,series);\n  return {k,entity:null,series,title,label:(list.length?(title+' · '+list.length+' entité'+(list.length>1?'s':'')):title)+' · dernières 24h'};\n}\nasync function aggregateHistory(k,entity){\n  const solarList=customEntityListForKey('pvPower');\n  const carPowerList=customEntityListForKey('carPower');\n  const carSocList=customEntityListForKey('carSoc');\n  const isSolar=k==='pvPower'||entityIsInConfiguredList(entity,solarList);\n  if(isSolar){\n    const all=[];\n    for(const id of solarList){const serie=normalizeHistorySeriesForKey('pvPower',id,await fetchHaHistory(id));if(serie.length>1)all.push(serie)}\n    let series=sumHistorySeries(all);\n    if(series.length<2){const local=localHistory('pvPower',solarList[0]||null);series=local.length>1?local:fallbackSeries('pvPower')}\n    return {k:'pvPower',entity:null,series,title:'Solar production',label:(solarList.length?('Total solar power · '+solarList.length+' entities'):'Total solar power')+' · dernières 24h'};\n  }\n  if(k==='carPower'||entityIsInConfiguredList(entity,carPowerList))return configuredHistory('carPower','sum','Car instant power');\n  if(k==='carSoc'||entityIsInConfiguredList(entity,carSocList))return configuredHistory('carSoc','avg','Car SOC');\n  const direct=entity||entityForKey(k);\n  let series=normalizeHistorySeriesForKey(k,direct,await fetchHaHistory(direct));\n  if(!series.length){const local=localHistory(k,direct);series=local.length>1?local:fallbackSeries(k)}\n  series=repairFlatHistoryWithLive(k,direct,series);\n  return {k,entity:direct,series,title:friendlyName(direct,k),label:(direct||'courbe locale')+' · dernières 24h'};\n}\nasync function openHistory(k){\n  const pack=await aggregateHistory(k,null);\n  document.getElementById('historyTitle').textContent=pack.title;\n  document.getElementById('historyEntity').textContent=pack.label;\n  document.getElementById('historyLive').textContent=currentHistoryText(pack.k,pack.entity,pack.entity?readEntity(pack.entity):read(pack.k));\n  document.getElementById('historyModal').classList.add('open');\n  drawHistory(pack.k,pack.series,pack.entity,pack.title,pack.label);\n}\nasync function openHistoryEntity(entity){\n  const k=keyForEntity(entity);\n  const pack=await aggregateHistory(k,entity);\n  document.getElementById('historyTitle').textContent=pack.title;\n  document.getElementById('historyEntity').textContent=pack.label;\n  document.getElementById('historyLive').textContent=currentHistoryText(pack.k,pack.entity,pack.entity?readEntity(pack.entity):read(pack.k));\n  document.getElementById('historyModal').classList.add('open');\n  drawHistory(pack.k,pack.series,pack.entity,pack.title,pack.label);\n}\ndocument.querySelectorAll('#closeHistory,#closeHistoryTop').forEach(b=>b.addEventListener('click',()=>document.getElementById('historyModal').classList.remove('open')));\ndocument.getElementById('historyModal').addEventListener('click',e=>{if(e.target.id==='historyModal')document.getElementById('historyModal').classList.remove('open')});\nfunction bindValueClicks(){const blocked=el=>{const v=el.closest('.invInnerView');return !!(v&&(v.id.endsWith('_commands')||v.id.endsWith('_diag')))||!!el.closest('.cmdRow,.diagGrid