      ["Entité statut raccourci maison 9", "Home shortcut 9 status entity"],
      ["Raccourci maison 10 actif", "Home shortcut 10 enabled"],
      ["Nom raccourci maison 10", "Home shortcut 10 name"],
      ["Entité raccourci maison 10", "Home shortcut 10 entity"],
      ["Entité statut raccourci maison 10", "Home shortcut 10 status entity"]
  ];
  // Longest first to avoid partial replacements winning before full labels.
  pairs.sort((a,b) => String(b[0]).length - String(a[0]).length);
  for (const p of pairs) {
    const from = String(p[0]);
    const to = String(p[1]);
    if (!from || from === to) continue;
    house = house.split(from).join(to);
  }
  house = house.split('Add up to 6 home sensors or commands in the top bar').join('Add up to 10 home sensors or commands in the top bar');
  return translateHouseHtmlForLanguage(house);
}

try {
  const moduleBaseDir = firstWritableDir(["/config/www/smart-modular-dashboard"]);
  fs.writeFileSync(moduleBaseDir + "/house.html", buildHomeShellHtml(), "utf8");
  node.status({ fill: "green", shape: "dot", text: "House module ecrit : " + moduleBaseDir + "/house.html" });
} catch (e) {
