  return null;
}
msg.topic = "build-shared-index-after-house";
msg.payload = "";
return msg;

// Legacy 4.1.12-alpha4: 4 standalone INT32 thresholds + two guarded source registers.
const topic=String(msg.topic||'');
const m=/^BMS_(\d+)\/control\/(dry[12]_(?:(?:trigger|release)_value|trigger_code))\/set$/i.exec(topic);
if(!m) return null;
const id=Number(m[1]), key=m[2].toLowerCase();
if(!Number.isInteger(id)||id<1||id>15){node.warn('DRY invalid BMS address');return null;}
if(global.get('bms_broadcasting')===true){node.warn('DRY write blocked: Broadcasting');return null;}
if(global.get('Authorize_Modify_Settings')!==true){node.warn('DRY write blocked: Modify Settings disabled');return null;}
const raw=String(msg.payload).trim();
const dryLabels = ["00 - OFF", "01 - Low SOC", "02 - Battery Over Voltage", "03 - Battery Under Voltage", "04 - Battery Cell Over Voltage", "05 - Battery Cell Under Voltage", "06 - Charge Over Current", "07 - Discharge Over Current", "08 - Battery over Temperature", "09 - MOSFET Over Temperature", "10 - SysAlarm", "11 - Battery Low Temperature", "12 - Remote Control", "13 - Above SOC", "14 - MOSFET Abnormal"];
const sourceCommand = key==='dry1_trigger_code' || key==='dry2_trigger_code';
let val;
if (sourceCommand) {
    const index=dryLabels.indexOf(raw);
    if (index>=0) val=index;
    else if (/^\d{1,2}$/.test(raw) && Number(raw)<=14) val=Number(raw);
    else {node.warn('DRY unknown source label/code');return null;}
} else {
    if(!/^-?\d+$/.test(raw)){node.warn('DRY integer required');return null;}
    val=Number(raw);
}
// Brief suppression of exactly identical repeated MQTT commands.
// alpha6: only one outstanding command per physical BMS/parameter.
const pendingKey='dry_alpha6_pending_BMS_'+id+'_'+key;
const outstanding=global.get(pendingKey);
if(outstanding && Number.isFinite(outstanding.deadline) && Date.now()<outstanding.deadline) {
    // Duplicate MQTT deliveries for the same requested value are harmless.
    // Preserve the safety lock if the user requests a different value mid-flight.
    if (outstanding.requested === val) {
        node.debug('DRY duplicate MQTT command ignored while STATIC verification is pending: '+key+' BMS_'+id);
    } else {
        node.warn('DRY write blocked: previous write awaiting STATIC readback '+key+' BMS_'+id);
    }
    return null;
}
const dedupKey='dry_alpha5_last_cmd_BMS_'+id+'_'+key;
const prev=context.get(dedupKey);
const now=Date.now();
if(prev && prev.value===val && now>=prev.time && now-prev.time<900) {
    node.debug('DRY duplicate command ignored: '+key+' BMS_'+id);
    return null;
}
let reg, data, words;
if(key==='dry1_trigger_code'||key==='dry2_trigger_code') {
    if(!Number.isInteger(val)||val<0||val>14){node.warn('DRY invalid source code');return null;}
    const snapshot=global.get('dry_alpha4_static_BMS_'+id);
    if(!snapshot || !Number.isFinite(snapshot.time) || (Date.now()-snapshot.time)>120000 || snapshot.time>Date.now()+1000) {
        node.warn('DRY source write blocked: missing/recent STATIC snapshot BMS_'+id);return null;
    }
    const pair=(key==='dry1_trigger_code') ? snapshot.dry1 : snapshot.dry2;
    if(!Array.isArray(pair)||pair.length!==2||!pair.every(v=>Number.isInteger(v)&&v>=0&&v<=255)){
        node.warn('DRY source write blocked: invalid shared register snapshot');return null;
    }
    reg=key==='dry1_trigger_code'?0x14e4:0x14e6;
    data=Buffer.from(key==='dry1_trigger_code'?[pair[0],val]:[val,pair[1]]);
