    reg={dry1_trigger_value:0x14f0,dry1_release_value:0x14f4,dry2_trigger_value:0x14f8,dry2_release_value:0x14fc}[key];
    if(reg===undefined)return null;
    if(!Number.isSafeInteger(val)||val < -100000||val >100000){node.warn('DRY raw threshold outside safety interval');return null;}
    data=Buffer.alloc(4);data.writeInt32BE(val,0);words=2;
}
const out=Buffer.from([id,0x10,(reg>>8)&255,reg&255,0,words,data.length,...data]);
let crc=0xffff;for(const x of out){crc^=x;for(let b=0;b<8;b++)crc=(crc&1)?((crc>>1)^0xa001):(crc>>1);}
msg.payload=Buffer.concat([out,Buffer.from([crc&255,(crc>>8)&255])]);
context.set(dedupKey,{value:val,time:now});
// Confirm only when a subsequent decoded STATIC sample matches the requested value.
// A queued command is NOT evidence of a successful Modbus write.
global.set(pendingKey,{bms:id,key:key,requested:val,register:reg,started:now,deadline:now+90000});
msg.dry_pending={bms:id,key,requested:val,register:reg};
node.warn('DRY write SENT, awaiting real STATIC readback: '+key+' BMS_'+id+' -> '+val);
return [msg, {payload:{bms:id,key:key,requested:val},topic:'DRY-READBACK-SCHEDULE'}];

const now=Date.now();
const fields=['dry1_trigger_code','dry2_trigger_code','dry1_trigger_value','dry1_release_value','dry2_trigger_value','dry2_release_value'];
for(let id=1;id<=15;id++) for(const key of fields){
    const token='dry_alpha6_pending_BMS_'+id+'_'+key;
    const p=global.get(token);
    if(p && Number.isFinite(p.deadline) && now>=p.deadline){
        node.warn('DRY STATIC READBACK TIMEOUT: BMS_'+id+' '+key+' requested '+p.requested+' (no matching STATIC frame within 90s)');
        global.set(token,null);
    }
