return null;

// Readback only. Do not send if pending command was already verified or expired.
const p=msg.payload||{};
const id=Number(p.bms),key=String(p.key||'');
if(!Number.isInteger(id)||id<1||id>15||!/^dry[12]_(trigger_code|trigger_value|release_value)$/.test(key))return null;
if(global.get('bms_broadcasting')===true)return null;
const pending=global.get('dry_alpha6_pending_BMS_'+id+'_'+key);
if(!pending||pending.requested!==p.requested||Date.now()>=pending.deadline)return null;
