// but addressed explicitly to the BMS which was just written.
const bytes=Buffer.from([id,0x10,0x16,0x1c,0,1,2,0,0]);
let crc=0xffff;
for(const b of bytes){crc^=b;for(let j=0;j<8;j++)crc=(crc&1)?((crc>>>1)^0xa001):(crc>>>1);}
msg.payload=Buffer.concat([bytes,Buffer.from([crc&255,(crc>>>8)&255])]);
msg.topic='Trame-1-statiques';
msg.dry_targeted_readback=true;
node.warn('DRY STATIC targeted readback requested: BMS_'+id+' '+key);
return msg;
